using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;
using Xunit;

namespace Sace.Api.Tests;

public class AdvancedLegalApiAndMigrationTests {
  [Fact] public async Task Legal_endpoints_require_jwt_and_accept_authenticated_evaluation(){using var factory=new SaceFactory();var anonymous=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync($"/api/operations/{Guid.NewGuid()}/legal")).StatusCode);var login=await anonymous.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());anonymous.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());Guid operationId;using(var scope=factory.Services.CreateScope())operationId=await scope.ServiceProvider.GetRequiredService<SaceDbContext>().TradeOperations.Select(x=>x.Id).FirstAsync();var response=await anonymous.PostAsync($"/api/operations/{operationId}/legal/evaluate",null);Assert.Equal(HttpStatusCode.OK,response.StatusCode);}

  [Fact] public async Task Future_reform_seed_is_verified_exact_and_idempotent_without_productive_rule(){using var factory=new SaceFactory();_ = factory.CreateClient();await DbSeeder.SeedAsync(factory.Services);await DbSeeder.SeedAsync(factory.Services);using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var sources=await db.OfficialLegalSources.Include(x=>x.Versions).ThenInclude(x=>x.Citations).Where(x=>x.Code=="DOF-LA-REFORMA-2026-10-23").ToListAsync();var source=Assert.Single(sources);Assert.Equal(SourceVerificationStatus.VERIFIED,source.Status);Assert.Equal("Decreto por el que se reforman y adicionan diversas disposiciones de la Ley Aduanera",source.Title);var version=Assert.Single(source.Versions);Assert.Equal("5802077",version.DofPublicationCode);Assert.Equal(SourceVerificationStatus.VERIFIED,version.VerificationStatus);Assert.Equal(new DateTime(2026,10,23,0,0,0,DateTimeKind.Utc),version.PublicationDate);Assert.Equal(new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),version.EffectiveFrom);Assert.Contains("Segundo Transitorio",version.VerificationNotes);var expected=new[]{"Ley Aduanera, artículo 151, primer párrafo, fracción VII","Ley Aduanera, artículo 153, segundo párrafo","Ley Aduanera, artículo 154, segundo párrafo","Ley Aduanera, artículo 177, fracción XII","Ley Aduanera, artículo 144, fracción XII, segundo párrafo","Ley Aduanera, artículo 185, fracciones I, II y III, segundo párrafo","Segundo Transitorio — disposiciones posteriores para el artículo 151, fracción VII"};foreach(var label in expected)Assert.Single(version.Citations,x=>x.CitationLabel==label);Assert.Equal(1,await db.SystemAuditLogs.CountAsync(x=>x.Action=="OFFICIAL_SOURCE_VERIFIED"&&x.EntityId==version.Id.ToString()));Assert.False(await db.NormativeRules.AnyAsync(x=>x.LegalStatus==LegalRuleStatus.VERIFIED&&x.LegalSourceCitations.Any(c=>c.OfficialSourceCitation.OfficialLegalSourceVersionId==version.Id)));}

  [Fact] public async Task Migration_is_incremental_and_down_is_scoped(){const string previous="20261026231346_ImmexInventoryControlV1";var directory=Path.Combine(Path.GetTempPath(),$"sace-s7-{Guid.NewGuid():N}");Directory.CreateDirectory(directory);var path=Path.Combine(directory,"migration.db");try{await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(previous);Assert.False(await Table(db,"LegalRuleConditions"));await migrator.MigrateAsync();Assert.True(await Table(db,"LegalRuleConditions"));Assert.True(await Table(db,"LegalEvaluationEvidence"));Assert.True(await Table(db,"LegalReviewDecisions"));await migrator.MigrateAsync(previous);Assert.False(await Table(db,"LegalRuleConditions"));Assert.True(await Table(db,"ImmexInventoryEntries"));Assert.True(await Table(db,"AuditResults"));}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(directory)&&Path.GetFullPath(directory).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase))Directory.Delete(directory,true);}}

  static async Task<bool> Table(SaceDbContext db,string name){await db.Database.OpenConnectionAsync();await using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=$name";var parameter=command.CreateParameter();parameter.ParameterName="$name";parameter.Value=name;command.Parameters.Add(parameter);return Convert.ToInt32(await command.ExecuteScalarAsync())==1;}
}
